gentle:{label:'穏やか',desc:'NP高・CP低。困ったように受け流す／おっとり・世話焼き',fit:function(t){return t.np+(1-t.cp)*0.5+t.a*0.15;}},
devoted:{label:'健気',desc:'NP・AC高。我慢して頑張る／尽くす・敬語',fit:function(t){return t.np*0.6+t.ac*0.8+(1-t.cp)*0.25;}},
cool:{label:'冷静',desc:'A高・FC低。観察して分析する／クール・理屈っぽい',fit:function(t){return t.a+(1-t.fc)*0.4+(1-t.np)*0.3;}},
free:{label:'奔放',desc:'FC高・AC低。素直に驚き、楽しむ／元気・天真爛漫',fit:function(t){return t.fc+(1-t.ac)*0.5+(1-t.cp)*0.2;}},
shy:{label:'恥じらい',desc:'AC高・FC低。赤くなって謝る／内気・おどおど',fit:function(t){return t.ac+(1-t.fc)*0.4+(1-t.cp)*0.3;}},
polite:{label:'敬語',desc:'誰にでも丁寧語で話す／礼儀正しい・物腰やわらか',fit:function(){return-1;}}
