HK.Load.def(12,'js/tie-rel.js',function(){
(function(){
'use strict';
var HK=window.HK;
function L(s){return s.split('|');}
var TR=(HK.TieRel={});
function own(ctx){return ctx&&ctx.scen&& /^(zombie|whiteroom|omega)$/.test(ctx.scen.id)?0.35:1;}
function both(a,b){return!!(HK.canLove&&HK.canLove(a,b)&&HK.canLove(b,a));}
function grow(ctx,a,b,k){var pf=ctx.pair(a,b);pf.tieGrow=pf.tieGrow||{};pf.tieGrow[k]=(pf.tieGrow[k]||0)+1;}
function has(ctx,a,b,ty){return HK.Ties&&HK.Ties.has?HK.Ties.has(ctx,a,b,ty):null;}
function warmth(ctx,a,b){var x=ctx.R(a,b),y=ctx.R(b,a);return(x.aff+y.aff+x.trust+y.trust)/4;}
function push(ev){var r0=ev.run;ev.run=function(ctx,a,b){var r=r0.apply(this,arguments);return HK.Attr&&HK.Attr.daily?HK.Attr.daily(ctx,a,b,r,ev.cat):r;};if(HK.COMMON)HK.COMMON.push(ev);}
var CLASSMATE={
pat:L('{a}と{b}は、同じクラスだったころの担任の口癖を同時に思い出して、声をそろえて笑った。|{a}「学生のころから全然変わらない｜学生のころから少しも変わらないな｜学生のころから全然変わりませんね」{b}「それ、褒めてる？｜それは、褒めているのか｜それ、褒めてますか」{a}「半分くらいは｜半分くらいはな｜半分くらいは褒めています」|{a}は{b}の字を見て、ノートを借りていたころを思い出した。癖のある字は、あのころのままだった。|{a}と{b}は、卒業アルバムの寄せ書きに誰が何を書いたかで小さく言い合った。どちらの記憶も、少しずつ間違っていた。|{a}は{b}の横顔に、窓際の席に座っていたころの面影を見た。|{a}「同じクラスだったの、もうずいぶん前のことになった｜同じクラスだったのも、もうずいぶん前のことになった｜同じクラスだったのも、もうずいぶん前のことになりました」{b}「数えたくない｜＝｜数えたくないです」'),
keep:L('{a}と{b}は、学生のころのあだ名で互いを呼んでみた。少し照れくさかったが、それだけで肩の力が抜けた。|{a}は{b}が困っているのに気づいて、学生のころと同じように、黙って半分を引き受けた。{b}も、あのころと同じように小さく礼を言った。|{a}「{b}がいると、学生のころに戻ったみたいで落ち着く｜{b}がいると、学生のころに戻ったようで落ち着く｜{b}がいると、学生のころに戻ったみたいで落ち着きます」{b}「{一人称}も。……今がいつなのか、忘れそうになる｜{一人称}もだ。……今がいつなのか、忘れそうになる｜{一人称}もです。……今がいつなのか、忘れそうになります」|{a}と{b}は、同じクラスにいた顔ぶれの近況を教え合った。知らない話ばかりで、二人とも少し笑った。'),
clash:L('{a}と{b}は、テストの点で張り合っていたころのように、どちらが先に片づけるかで競い合った。終わってみると、二人とも少し笑っていた。|{b}「学生のころは、{a}に一度も勝てなかった｜＝｜学生のころは、{a}に一度も勝てませんでした」{a}「今度は{一人称}が勝つかもしれない｜＝｜今度は{一人称}が勝つかもしれませんよ」{b}「言ったね｜言ったな｜言いましたね」|{a}と{b}は、昔の文化祭でどちらの案が通ったかを蒸し返して、しばらく言い合いになった。'),
grow:L('{a}は、学生のころ{b}に言えなかったことを、ようやく口にした。{a}「あのとき、かばってくれてありがとう｜あのとき、かばってくれて感謝している｜あのとき、かばってくれてありがとうございました」{b}はしばらく黙って、それから「覚えてたんだ｜覚えていたのか｜覚えていたんですね」と小さく笑った。|{a}と{b}は、卒業してから会わなかった年月の話をした。空白は思ったより短く感じられた。昔の同級生は、いつの間にかいちばん話しやすい相手になっていた。|{b}「同じクラスだったころより、今の{a}のほうがずっと近い気がする｜＝｜同じクラスだったころより、今の{a}のほうがずっと近い気がします」{a}「{一人称}も、そう思ってた｜{一人称}も、そう思っていた｜{一人称}も、そう思っていました」'),
love:L('{a}「学生のころ、{一人称}、{b}のことずっと見てた｜学生のころ、{一人称}は{b}のことをずっと見ていた｜学生のころ、{一人称}、{b}のことをずっと見ていました」{b}「……知らなかった｜＝｜……知りませんでした」{a}「言わなかったから｜言わなかったからな｜言いませんでしたから」――二人のあいだで、昔の教室の空気が少しだけ違う色に変わった。|{b}は{a}の手をとった。{b}「同じクラスだったころには、こんなふうになるなんて思わなかった｜同じクラスだったころには、こんなふうになるとは思わなかった｜同じクラスだったころには、こんなふうになるなんて思いませんでした」{a}は答えのかわりに、その手を握り返した。|{a}は{b}に、卒業式の日に言えなかった言葉があったと打ち明けた。{b}「今なら、聞ける｜＝｜今なら、聞けます」{a}は少し迷ってから、ずっとしまっていた気持ちを口にした。')
};
push({
id:'tie_classmate',label:'同級生と昔話で笑い合う',cat:'bond',scope:'pair',
when:function(ctx,a,b){return!!has(ctx,a,b,'classmate');},
w:function(ctx){return 1*own(ctx);},
run:function(ctx,a,b){
var ra=ctx.R(a,b),rb=ctx.R(b,a),k;
var g=warmth(ctx,a,b);
if(both(a,b)&&ra.att>30&&rb.att>22&&g>30&&ctx.rng()<0.45)k='love';
else if(g>32&&ctx.rng()<0.35)k='grow';
else if((ra.ten>20||rb.ten>20||a.tr.cp>0.6)&&ctx.rng()<0.35)k='clash';
else k=ctx.rng()<0.55?'pat':'keep';
if(k==='love'){ctx.mod2(a,b,{att:7,aff:4},{att:7,aff:4});grow(ctx,a,b,'classmate');}
else if(k==='grow'){ctx.mod2(a,b,{aff:6,trust:6},{aff:6,trust:6});grow(ctx,a,b,'classmate');}
else if(k==='clash')ctx.mod2(a,b,{ten:4,aff:1},{ten:4,trust:2});
else if(k==='keep')ctx.mod2(a,b,{aff:3,trust:4},{aff:3,trust:4});
else ctx.mod2(a,b,{aff:3,trust:2},{aff:3,trust:2});
return{cat:k==='love'?'romance':k==='clash'?'conflict':'bond',text:ctx.t(ctx.pick(CLASSMATE[k]),a,b),why:a.name+'と'+b.name+'は同級生'+{pat:'：昔の思い出',keep:'：変わらない気安さ',clash:'：昔からの張り合い',grow:'：昔話からの再接近',love:'：昔の同級生が特別な人に'}[k]};
}
});
var COLLEAGUE={
keep:L('{a}は{b}の分の作業を、何も言わずに半分引き取った。{b}「助かる。……借りがまた増えた｜助かる。……借りがまた増えたな｜助かります。……借りがまた増えました」{a}「職場に戻ったら、まとめて返して｜職場に戻ったら、まとめて返せ｜職場に戻ったら、まとめて返してください」|{a}と{b}は、仕事でやっていたのと同じように、やることを書き出して分担した。段取りが決まると、二人とも少し落ち着いた。|{b}「{a}と同じ職場でよかった。知らない人ばかりだったら、たぶん心が折れてた｜{a}と同じ職場でよかった。知らない人間ばかりだったら、たぶん心が折れていた｜{a}と同じ職場でよかったです。知らない人ばかりだったら、たぶん心が折れていました」{a}「{一人称}も、同じことを思ってた｜{一人称}も、同じことを思っていた｜{一人称}も、同じことを思っていました」|{a}は{b}の疲れた顔を見て、職場でいつもそうしていたように、温かい飲み物を黙って置いた。'),
grow:L('{a}と{b}は、職場では一度もしたことのない話をした。家族のこと、昔の夢のこと。同僚という言葉だけでは足りない距離になっていた。|{a}「仕事に戻っても、こうやって話せたらいいな｜仕事に戻っても、こうして話せたらいい｜仕事に戻っても、こうやって話せたらいいですね」{b}「なら、まずは昼休みに｜なら、まずは昼休みにだ｜なら、まずは昼休みにしましょう」――仕事の外での約束は、二人とも初めてだった。|{b}は{a}に、職場では誰にも言えなかった失敗を打ち明けた。{a}は笑わずに聞いて、自分の失敗も一つ話した。'),
love:L('{a}は{b}の横顔を見て、職場で隣にいたころにはなかった気持ちに気づいた。{a}「{b}、{一人称}……同僚のままでいるの、やめたいかもしれない｜{b}、{一人称}は……同僚のままでいるのを、やめたいのかもしれない｜{b}、{一人称}……同僚のままでいるのを、やめたいのかもしれません」|{b}は{a}の手に、自分の手を重ねた。仕事の話は、もう出てこなかった。{b}「職場では、{a}のこんな顔、見たことなかった｜職場では、{a}のこんな顔は見たことがなかった｜職場では、{a}のこんな顔、見たことがありませんでした」{a}「{b}の前だけ｜{b}の前だけだ｜{b}の前だけです」|{a}と{b}は、職場で交わしたどの言葉より短い言葉で、互いの気持ちを確かめた。同僚と呼ぶには、もう近すぎた。')
};
push({
id:'tie_colleague2',label:'同僚の連携と仕事の外の顔',cat:'bond',scope:'pair',
when:function(ctx,a,b){return!!has(ctx,a,b,'colleague');},
w:function(ctx){return 0.6*own(ctx);},
run:function(ctx,a,b){
var ra=ctx.R(a,b),rb=ctx.R(b,a),g=warmth(ctx,a,b),k;
if(both(a,b)&&ra.att>32&&rb.att>24&&g>30&&ctx.rng()<0.45)k='love';
else if(g>30&&ctx.rng()<0.4)k='grow';
else k='keep';
if(k==='love'){ctx.mod2(a,b,{att:7,aff:4},{att:7,aff:4});grow(ctx,a,b,'colleague');}
else if(k==='grow'){ctx.mod2(a,b,{aff:6,trust:6},{aff:6,trust:5});grow(ctx,a,b,'colleague');}
else ctx.mod2(a,b,{trust:4,aff:2},{trust:4,aff:2});
return{cat:k==='love'?'romance':'bond',text:ctx.t(ctx.pick(COLLEAGUE[k]),a,b),why:a.name+'と'+b.name+'は同僚'+{keep:'：いつもの分担',grow:'：仕事の外の顔',love:'：同僚から恋へ'}[k]};
}
});
var BOSS={
a:L('{a}は{b}の報告を最後まで聞いてから、短く頷いた。{a}「よくやった｜＝｜よくやりましたね」{b}は背筋を伸ばしたまま、少しだけ口元を緩めた。|{a}は危ない役目を{b}に回さず、黙って自分で引き受けた。部下を守るのが上司の仕事だと思っていた。|{a}は{b}の顔色を見て、手を止めさせた。{a}「今日はもう休んで。これは指示｜今日はもう休め。これは指示だ｜今日はもう休んでください。これは指示です」|{a}「判断は任せる。責任は{一人称}が取る｜＝｜判断は任せます。責任は{一人称}が取ります」{b}は一瞬目を見開いて、それから力強く頷いた。'),
b:L('{b}は{a}の指示を待たずに、次に要るものを先に揃えておいた。{a}は気づいて、何も言わずに頷いた。|{b}は{a}の背中を見ながら、職場で初めて叱られた日のことを思い出した。あの日から、ずっとこの人の下で働いてきた。|{b}「それは{一人称}がやる。{a}は全体を見ていて｜それは{一人称}がやる。{a}は全体を見ていろ｜それは{一人称}がやります。{a}は全体を見ていてください」{a}は少し驚いて、それから任せた。|{b}は{a}の癖を誰よりも知っていた。考えごとをするとき、決まって腕を組むことも。'),
clash:L('{b}は初めて{a}の指示に異を唱えた。{a}は眉をひそめたが、最後まで聞いて、{b}の案を採った。|{a}と{b}は進め方で意見が割れた。職場なら{a}の一言で決まるところだが、今は{b}も引かなかった。|{a}「{b}、それは命令違反だよ｜{b}、それは命令違反だ｜{b}、それは命令違反です」{b}「分かってる。でも、こっちのほうが{a}を危ない目に遭わせずに済む｜分かっている。だが、こちらのほうが{a}を危ない目に遭わせずに済む｜分かっています。でも、こちらのほうが{a}を危ない目に遭わせずに済みます」'),
keep:L('{a}は{b}に、仕事のときと同じ調子で「いつもの手順で｜いつもの手順でやれ｜いつもの手順でお願いします」と言った。{b}もいつもの調子で応じた。慣れたやり取りが、二人を落ち着かせた。|{b}は{a}の分の食事を、先に取り分けておいた。{a}「部下に気を遣わせる上司って、どうなんだろう｜部下に気を遣わせる上司というのは、どうなのだろう｜部下に気を遣わせる上司って、どうなんでしょう」{b}「{一人称}がやりたくてやってる｜{一人称}がやりたくてやっている｜{一人称}がやりたくてやっているんです」|{a}と{b}は、職場で何度も乗り越えてきた修羅場の話をした。あのときも、二人でどうにかした。'),
grow:L('{a}は{b}に、上司としてではなく、一人の人として弱音をこぼした。{b}は黙って最後まで聞いた。{b}「肩書きなんて、今はいらないと思う｜肩書きなど、今はいらないと思う｜肩書きなんて、今はいらないと思います」――二人のあいだの上下が、少しだけ平らになった。|{a}「{b}、今のは命令じゃない。お願い｜{b}、今のは命令ではない。頼みだ｜{b}、今のは命令ではありません。お願いです」{b}は驚いて{a}を見て、それから笑った。{b}「お願いなら、喜んで引き受ける｜頼みなら、喜んで引き受ける｜お願いなら、喜んで引き受けます」|{b}が{a}の失敗を黙って埋めた。{a}は礼を言ってから、つけ加えた。{a}「職場に戻ったら、{b}を部下じゃなくて、同じ目線の相手として頼りたい｜職場に戻ったら、{b}を部下ではなく、同じ目線の相手として頼りたい｜職場に戻ったら、{b}を部下ではなく、同じ目線の相手として頼りたいです」'),
love:L('{b}は{a}を見つめた。{b}「職場の外では、{a}を上司として見られない｜＝｜職場の外では、{a}を上司として見られません」{a}はしばらく黙って、{b}の名前を呼んだ。肩書きのない呼び方だった。|{a}は{b}の髪に触れかけて、手を止めた。{a}「部下にこんなことを思うなんて、上司失格だね｜部下にこんなことを思うとは、上司失格だ｜部下にこんなことを思うなんて、上司失格です」{b}「なら、今だけ上司をやめて｜なら、今だけ上司をやめろ｜なら、今だけ上司をやめてください」|{a}と{b}は、職場では決して見せない顔で向き合った。指示も報告もない言葉が、二人のあいだに初めて落ちた。')
};
push({
id:'tie_boss',label:'上司の責任と部下の支え',cat:'help',scope:'pair',
when:function(ctx,a,b){return!!has(ctx,a,b,'boss');},
w:function(ctx){return 1*own(ctx);},
run:function(ctx,a,b){
var t=has(ctx,a,b,'boss'),S=ctx.chars[t.a],K=ctx.chars[t.b];
var rs=ctx.R(S,K),rk=ctx.R(K,S),g=warmth(ctx,S,K),k;
if(both(S,K)&&rk.att>32&&rs.att>24&&g>32&&ctx.rng()<0.45)k='love';
else if(g>34&&ctx.rng()<0.35)k='grow';
else if((rs.ten>22||rk.ten>22||K.tr.cp>0.62)&&ctx.rng()<0.35)k='clash';
else{var x=ctx.rng();k=x<0.38?'a':x<0.76?'b':'keep';}
if(k==='love'){ctx.mod2(S,K,{att:7,aff:4},{att:7,aff:4});grow(ctx,S,K,'boss');}
else if(k==='grow'){ctx.mod2(S,K,{trust:7,aff:5},{trust:6,aff:6});grow(ctx,S,K,'boss');}
else if(k==='clash')ctx.mod2(S,K,{ten:5,trust:2},{ten:4,trust:2});
else if(k==='a')ctx.mod2(S,K,{aff:2,trust:2},{trust:5,aff:3});
else if(k==='b')ctx.mod2(S,K,{trust:5,aff:3},{aff:2,trust:2});
else ctx.mod2(S,K,{trust:4,aff:2},{trust:4,aff:2});
return{cat:k==='love'?'romance':k==='clash'?'conflict':k==='grow'||k==='keep'?'bond':'help',text:ctx.t(ctx.pick(BOSS[k]),S,K),why:S.name+'（上司）と'+K.name+'（部下）'+{a:'：上司の責任',b:'：部下の支え',clash:'：部下の反論',keep:'：いつものやり取り',grow:'：肩書きの外の信頼',love:'：上司と部下を越えて'}[k]};
}
});
var SPOUSE={
warm:L('{a}は何も言わずに、{b}の好きな濃さで飲み物を淹れた。何年も一緒にいれば、それくらいは分かる。|{b}は{a}の寝癖を指で直した。{a}「家みたいだな｜＝｜家みたいですね」{b}「家じゃなくても、二人なら家みたいなものでしょ｜家でなくても、二人なら家のようなものだろう｜家じゃなくても、二人なら家みたいなものでしょう」|{a}と{b}は、帰ったら何を食べるかで小さく言い合った。結局、いつもの店に決まった。'),
keep:L('{a}は{b}の手を取って、薬指の指輪を親指でなぞった。{b}は黙って、その手を握り返した。|{b}「無理しないって、約束したよね｜無理はしないと、約束したはずだ｜無理しないって、約束しましたよね」{a}「……した｜＝｜……しました」{b}「じゃあ守って｜なら守れ｜じゃあ守ってください」――{a}は小さく笑って頷いた。|{a}と{b}は、どちらが先に寝るかで押し問答をした。結局、肩を寄せたまま二人とも起きていた。'),
grow:L('{a}は{b}に、結婚したばかりのころの話をした。{b}は途中で笑い出し、それから少し泣いた。|{b}は{a}の背中に額を押しつけた。{b}「生きて帰ったら、もう一回、式を挙げたい｜生きて帰ったら、もう一度、式を挙げたい｜生きて帰ったら、もう一回、式を挙げたいです」{a}「何回でも｜何回でもだ｜何回でも挙げましょう」|{a}「{b}と一緒になって、よかった｜＝｜{b}と一緒になって、よかったです」――改めて言われて、{b}は照れくさそうに目を逸らした。'),
cold:L('{a}と{b}は、同じ部屋にいても目を合わせなかった。話すのは、必要なことだけだった。|{b}は{a}の言葉に、短く「そう｜そうか｜そうですか」とだけ返した。いつからこうなったのか、二人とも思い出せなかった。|{a}は{b}の隣に座りかけて、一つ空けた席に腰を下ろした。'),
thaw:L('{a}は、{b}が昔と同じ癖で髪を耳にかけるのを見た。それだけで、胸の奥の何かが少しほどけた。|{b}「……ごめん。ずっと、ちゃんと話してなかった｜……すまない。ずっと、きちんと話していなかった｜……ごめんなさい。ずっと、ちゃんと話していませんでした」{a}は少し黙ってから、「こっちこそ｜こちらこそ、すまなかった｜こちらこそ、すみませんでした」と言った。|危ない場面で、{a}は迷わず{b}の手を引いた。手を離したあと、二人はしばらく何も言わなかったが、その沈黙は前ほど冷たくなかった。'),
separated:L('{a}と{b}は、別々に暮らすようになってから、初めて同じ場所で夜を過ごした。気まずさのほうが勝っていた。|{b}は{a}の荷物に、まだ二人で買ったキーホルダーが付いているのに気づいた。何も言わなかった。|{a}「元気だった？｜元気だったか｜お元気でしたか」{b}「……まあね｜……まあな｜……まあ、元気です」――それ以上、どちらも続けられなかった。'),
ex:L('{a}と{b}は、元夫婦らしい距離で並んで座った。近すぎず、遠すぎず。|{b}は{a}の好みを覚えていた自分に気づいて、少しだけ苦笑いした。|{a}「相変わらずだな｜＝｜相変わらずですね」{b}「そっちこそ｜そっちこそな｜そちらこそですよ」――言い慣れたやり取りに、二人とも少しだけ肩の力を抜いた。'),
mature:L('{a}が空になった器を置くと、{b}は何も言わずに水を足した。長年連れ添った二人には、それで十分だった。|{b}「……疲れたでしょ｜……疲れただろう｜……お疲れでしょう」{a}「少しね｜少しな｜少しだけです」――それきり会話は途切れたが、{a}は{b}の肩に、そっと手を置いた。|{a}と{b}は並んで座り、同じものを眺めていた。言葉はほとんどなかった。若いころなら気まずかった沈黙が、今はいちばん落ち着いた。|{b}は{a}の上着のほつれに気づいて、黙って繕い始めた。{a}は小さく「ありがとう｜感謝する｜ありがとうございます」とだけ言い、{b}は「うん｜ああ｜はい」とだけ返した。'),
back:L('{a}は{b}の名前を、離婚する前と同じ呼び方で呼んだ。{b}は振り返って、何かを言いかけてやめた。|{b}「もう一回、やり直せると思う？｜もう一度、やり直せると思うか｜もう一回、やり直せると思いますか」{a}はすぐには答えず、{b}の手を取った。')
};
function spouseTie(ctx,a,b){
var l=HK.Ties&&HK.Ties.all?HK.Ties.all(ctx,a,b):[];
for(var i=0;i<l.length;i++)if(l[i].spouse)return l[i];
return null;
}
TR.spouse=spouseTie;
push({
id:'tie_spouse',label:'連れ添った二人のいつもの時間',cat:'bond',scope:'pair',
when:function(ctx,a,b){return!!spouseTie(ctx,a,b);},
w:function(ctx){return 1.5*own(ctx);},
run:function(ctx,a,b){
var t=spouseTie(ctx,a,b),g=warmth(ctx,a,b),st=t.type==='ex'?'ex':t.married||'warm',k;
if(st==='warm'){var x=ctx.rng();k=g>38&&x<0.3?'grow':x<0.65?'warm':'keep';}
else if(st==='mature'){var x2=ctx.rng();k=x2<0.5?'mature':x2<0.8?'warm':'keep';}
else if(st==='cold'||st==='separated')k=g>30&&ctx.rng()<0.35?'thaw':st==='cold'?'cold':'separated';
else k=both(a,b)&&g>34&& !ctx.pair(a,b).couple&&ctx.rng()<0.25?'back':'ex';
if(k==='grow'||k==='keep'||k==='warm'||k==='mature')ctx.mod2(a,b,{aff:3,trust:3},{aff:3,trust:3});
else if(k==='cold'||k==='separated')ctx.mod2(a,b,{ten:3},{ten:3});
else if(k==='thaw'){ctx.mod2(a,b,{aff:6,trust:5,ten: -6},{aff:6,trust:5,ten: -6});grow(ctx,a,b,'spouse');if(g>45)t.married='';}
else if(k==='back'){ctx.mod2(a,b,{att:6,aff:5},{att:6,aff:5});grow(ctx,a,b,'spouse');}
else ctx.mod2(a,b,{aff:1},{aff:1});
if(k==='grow')grow(ctx,a,b,'spouse');
var lab=HK.tieLabel?HK.tieLabel(t):'夫婦';
return{cat:k==='back'?'romance':k==='cold'||k==='separated'?'conflict':'bond',text:ctx.t(ctx.pick(SPOUSE[k]),a,b),why:a.name+'と'+b.name+'（'+lab+'）'+{warm:'：いつもの二人',mature:'：長年連れ添った二人の労い',keep:'：夫婦の約束',grow:'：絆が深まる',cold:'：冷えたまま',thaw:'：わだかまりが少しほどける',separated:'：別居中の気まずさ',ex:'：元夫婦の距離',back:'：やり直しの気配'}[k]};
}
});
var BENE={
a:L('{a}は{b}が無理をしていないか、何度も気にかけた。昔助けたときから、{b}のことはどうしても放っておけなかった。|{a}「昔のことなんて、もう気にしなくていいのに｜昔のことなど、もう気にしなくていい｜昔のことなんて、もう気にしなくていいんですよ」{b}は首を振った。忘れられるはずがなかった。|{a}は{b}が笑っているのを見て、助けてよかったと、あらためて思った。'),
b:L('{b}は{a}の荷物を、言われる前に持っていた。あの日の恩を思えば、これくらい何でもなかった。|{b}は{a}が眠ったのを確かめてから、そっと上着をかけた。昔、{a}が自分にしてくれたのと同じように。|{b}「{a}がいなかったら、今の{一人称}はいない｜＝｜{a}がいなかったら、今の{一人称}はいません」{a}「大げさすぎ｜大げさすぎる｜大げさすぎます」{b}「大げさじゃない｜大げさではない｜大げさじゃありません」|{b}は{a}の言葉なら、どんな小さなことでも覚えていた。'),
keep:L('{a}と{b}は、出会ったころの話をした。{b}は何度でも礼を言い、{a}は何度でも照れくさそうに手を振った。|{b}は{a}を守るように隣に立った。{a}は苦笑いしたが、その場を譲った。|{a}は{b}に、困ったら頼っていいと言った。{b}「頼ってばかりだから、今度は{一人称}が｜頼ってばかりだから、今度は{一人称}が助ける｜頼ってばかりですから、今度は{一人称}が助けます」{a}「その気持ちだけで十分｜その気持ちだけで十分だ｜その気持ちだけで十分です」'),
grow:L('{b}は危ないところで{a}の手を引いた。{a}は息を整えてから、{b}を見た。{a}「……昔と逆になった｜……昔と逆になったな｜……昔と逆になりましたね」{b}「やっと、少しだけ返せた｜＝｜やっと、少しだけ返せました」|{b}は{a}が倒れかけたとき、迷わず肩を貸した。{a}「助けられる日が来るなんて｜助けられる日が来るとは｜助けられる日が来るなんて、思いませんでした」{b}「ずっと、この日を待ってた｜ずっと、この日を待っていた｜ずっと、この日を待っていました」|{a}「もう恩なんて言わないで。{b}は{一人称}の大事な人だから｜もう恩などと言うな。{b}は{一人称}の大事な人だ｜もう恩なんて言わないでください。{b}は{一人称}の大事な人なんですから」――{b}はうつむいて、しばらく顔を上げられなかった。'),
love:L('{b}は{a}の手を握った。{b}「最初は恩返しのつもりだった。でも今は、ただ{a}のそばにいたい｜最初は恩返しのつもりだった。だが今は、ただ{a}のそばにいたい｜最初は恩返しのつもりでした。でも今は、ただ{a}のそばにいたいんです」{a}は目を伏せて、その手を離さなかった。|{a}は{b}を見て、助けたあの日にはなかった気持ちに気づいた。守る相手だった{b}が、いつの間にか隣に並んでいた。{a}「{b}、{一人称}……」その先は、{b}が先に言った。')
};
push({
id:'tie_benefactor',label:'恩人の気遣いと消えない感謝',cat:'help',scope:'pair',
when:function(ctx,a,b){return!!has(ctx,a,b,'benefactor');},
w:function(ctx){return 1*own(ctx);},
run:function(ctx,a,b){
var t=has(ctx,a,b,'benefactor'),S=ctx.chars[t.a],K=ctx.chars[t.b];
var rs=ctx.R(S,K),rk=ctx.R(K,S),g=warmth(ctx,S,K),k;
var weak=S.stress>45||S.hp<60;
if(both(S,K)&&rk.att>32&&rs.att>24&&g>34&&ctx.rng()<0.4)k='love';
else if((g>34||weak)&&ctx.rng()<(weak?0.5:0.3))k='grow';
else{var x=ctx.rng();k=x<0.35?'a':x<0.78?'b':'keep';}
if(k==='love'){ctx.mod2(S,K,{att:7,aff:4},{att:7,aff:4});grow(ctx,S,K,'benefactor');}
else if(k==='grow'){ctx.mod2(S,K,{aff:7,trust:8},{aff:4,trust:4});ctx.stress(S,-8);grow(ctx,S,K,'benefactor');}
else if(k==='a')ctx.mod2(S,K,{aff:3},{aff:3,trust:3});
else if(k==='b')ctx.mod2(S,K,{aff:4,trust:4},{aff:2});
else ctx.mod2(S,K,{aff:3,trust:3},{aff:3,trust:3});
return{cat:k==='love'?'romance':k==='a'||k==='b'||k==='grow'?'help':'bond',text:ctx.t(ctx.pick(BENE[k]),S,K),why:S.name+'（恩人）と'+K.name+'（恩を受けた側）'+{a:'：恩人の気遣い',b:'：消えない感謝',keep:'：恩でつながる二人',grow:'：恩返し',love:'：恩が恋に変わる'}[k]};
}
});
var REL={
pat:L('{a}と{b}は、親戚の集まりでいつも隅の席に並んでいたことを思い出して笑った。|{a}「田舎の家の縁側、覚えてる？｜田舎の家の縁側を、覚えているか｜田舎の家の縁側、覚えていますか」{b}「夏になると、二人でスイカの種を飛ばしてた｜夏になると、二人でスイカの種を飛ばしていた｜夏になると、二人でスイカの種を飛ばしていましたね」|{a}は{b}の仕草に、親族の誰かの面影を見つけた。血のつながりは、こういうところに出るらしい。|{b}「{a}とは、法事くらいでしか会わなかったのに｜{a}とは、法事くらいでしか会わなかったのにな｜{a}とは、法事くらいでしか会っていませんでしたよね」{a}「こんなところで会うなんて｜こんなところで会うとは｜こんなところで会うなんて、思いませんでした」'),
keep:L('{a}は{b}の分まで食べ物を取っておいた。親戚の家で、いつもそうしてもらっていたのと同じだった。|{a}と{b}は、家族には言えない愚痴を互いにこぼした。近すぎず遠すぎない親族だから、言えることがあった。|{b}は{a}の寝癖を見て、昔から変わらないと笑った。{a}は少しむくれて、それでも直そうとはしなかった。'),
grow:L('{a}と{b}は、落ち着いたら一緒に親戚の家へ顔を出そうと約束した。遠い親族だった二人が、家族と呼べる距離になっていた。|{b}「{a}は、{一人称}にとっていちばん頼れる家族だよ｜{a}は、{一人称}にとっていちばん頼れる家族だ｜{a}は、{一人称}にとっていちばん頼れる家族です」{a}は照れくさそうに笑って、{b}の背中を軽く叩いた。|{a}は{b}が泣きそうになっているのに気づいて、子どものころのように頭に手を置いた。{a}「大丈夫。親族なんだから、頼っていい｜大丈夫だ。親族なのだから、頼っていい｜大丈夫です。親族なんですから、頼っていいんですよ」'),
love:L('{a}は{b}の手を握ったまま、離せなくなった。{a}「親族なのに、こんな気持ちになるなんて｜親族なのに、こんな気持ちになるとは｜親族なのに、こんな気持ちになるなんて、思いませんでした」{b}「……{一人称}も、同じ｜……{一人称}も、同じだ｜……{一人称}も、同じです」|{b}は{a}を見つめた。親戚の集まりで隣に座っていたころとは、もう違う目だった。{b}「{a}を、家族としてだけ見るのは無理かもしれない｜＝｜{a}を、家族としてだけ見るのは無理かもしれません」')
};
push({
id:'tie_relative',label:'親族どうしの思い出と助け合い',cat:'help',scope:'pair',
when:function(ctx,a,b){return!!has(ctx,a,b,'relative');},
w:function(ctx){return 1*own(ctx);},
run:function(ctx,a,b){
var t=has(ctx,a,b,'relative'),ra=ctx.R(a,b),rb=ctx.R(b,a),g=warmth(ctx,a,b),k;
if(t.love==='ok'&&both(a,b)&&ra.att>28&&rb.att>22&&g>32&&ctx.rng()<0.4)k='love';
else if(g>32&&ctx.rng()<0.35)k='grow';
else k=ctx.rng()<0.55?'pat':'keep';
if(k==='love'){ctx.mod2(a,b,{att:6,aff:4},{att:6,aff:4});grow(ctx,a,b,'relative');}
else if(k==='grow'){ctx.mod2(a,b,{aff:7,trust:6},{aff:7,trust:6});grow(ctx,a,b,'relative');}
else if(k==='keep')ctx.mod2(a,b,{aff:3,trust:4},{aff:3,trust:4});
else ctx.mod2(a,b,{aff:3,trust:2},{aff:3,trust:2});
return{cat:k==='love'?'romance':k==='pat'?'bond':'help',text:ctx.t(ctx.pick(REL[k]),a,b),why:a.name+'と'+b.name+'は親族'+{pat:'：親戚の思い出',keep:'：気安い助け合い',grow:'：家族としての絆',love:'：親族を越えた想い'}[k]};
}
});
var WS={
a:L('{a}は{b}が通ったあとまで、丁寧に片づけて回った。{b}のためにできることなら、どんな小さなことでも嬉しかった。|{a}は{b}の言葉を一つも聞き漏らすまいと、じっと耳を傾けていた。|{a}「{b}のためなら、{一人称}は何でもする｜＝｜{b}のためなら、{一人称}は何でもします」――その声には、迷いが一つもなかった。|{a}は{b}の分の食事を先に用意して、自分の分には手をつけなかった。|{a}は{b}を危ないものから遠ざけるように、いつも半歩前に立っていた。'),
back:{
'':L('{b}は{a}がなぜそこまでしてくれるのか分からず、首をかしげた。{b}「{a}って、誰にでもこうなの？｜{a}は、誰にでもこうなのか｜{a}は、誰にでもこうなんですか」{a}は答えずに、ただ微笑んだ。|{b}は{a}の視線に気づかないまま、別の話を始めた。{a}はそれでも満ち足りていた。|{b}は{a}の差し出したものを、何の気なしに受け取った。{a}にとっては、それが何よりの恵みだった。'),
accept:L('{b}は{a}の差し出したものを、当たり前のように受け取った。{b}「ありがとう｜感謝する｜ありがとうございます」――その一言で、{a}の一日は報われた。|{b}は{a}の頭に手を置いた。{b}「{a}は、本当によく尽くしてくれる｜＝｜{a}は、本当によく尽くしてくれますね」{a}は目を閉じて、その手の重みを確かめた。|{b}は{a}の献身を、静かに受け入れていた。{a}が隣に控えていることが、もう当たり前になっていた。'),
confused:L('{b}は{a}の献身に、困ったように眉を寄せた。{b}「そこまでしなくていい。……正直、少し重い｜＝｜そこまでしなくていいです。……正直、少し重いです」{a}は頷いたが、次の日も同じように尽くした。|{b}は{a}から目を逸らした。どう応えればいいのか分からなかった。{a}は、それでも{b}のそばを離れなかった。|{b}「{一人称}はそんな立派な人間じゃない｜{一人称}はそんな立派な人間ではない｜{一人称}はそんな立派な人間ではありません」{a}「知ってる。それでも、{b}がいい｜知っている。それでも、{b}がいい｜知っています。それでも、{b}がいいんです」{b}は返す言葉を見つけられなかった。'),
dominate:L('{b}は{a}に、わざと面倒な用事を言いつけた。{a}は嫌な顔一つせず、むしろ嬉しそうに従った。{b}は、その従順さを確かめるように小さく笑った。|{b}「{a}は、{一人称}の言うことなら何でも聞くんだよね｜{a}は、{一人称}の言うことなら何でも聞くのだろう｜{a}は、{一人称}の言うことなら何でも聞くんですよね」{a}「うん｜ああ｜はい」――ためらいのない返事に、{b}は満足そうに目を細めた。|{b}は{a}に、ほかの誰とも口をきかないよう言いつけた。{a}は黙ってうなずいた。{b}の言葉は、{a}にとって何より重かった。'),
cherish:L('{b}は{a}の手を取って、その指先の傷に気づいた。{b}「{a}、自分のことも大事にして。お願い｜{a}、自分のことも大事にしろ。頼む｜{a}、自分のことも大事にしてください。お願いです」{a}は戸惑って、それからおずおずと頷いた。|{b}は{a}に、自分の分の食事を半分渡した。{b}「{a}が倒れたら、{一人称}が困る｜＝｜{a}が倒れたら、{一人称}が困ります」{a}は受け取った器を、両手で大事そうに抱えた。|{b}は{a}の名前を、ほかの誰を呼ぶときよりも柔らかく呼んだ。{a}はそのたびに、胸の奥が温かくなった。')
},
spurn:L('{b}は{a}を冷たく突き放した。{a}は少しだけ俯いて、それでも{b}の背中を見送った。{a}「嫌われても、{一人称}の想いは変わらない｜＝｜嫌われても、{一人称}の想いは変わりません」|{b}に避けられても、{a}は{b}の無事だけを祈っていた。見返りを求めたことは、一度もなかった。|{b}に投げつけられた言葉を、{a}は胸の奥にしまい込んだ。{b}から向けられたものなら、痛みでも手放せなかった。|{b}「もう、{一人称}に構わないで｜もう、{一人称}に構うな｜もう、{一人称}に構わないでください」{a}「構わない。でも、離れもしない｜構わない。だが、離れもしない｜構いません。でも、離れもしません」――{a}は一歩だけ下がって、そこから{b}を見守り続けた。'),
keep:L('{a}は{b}のそばに控え、{b}が何か言う前に必要なものを差し出した。それが{a}にとっての祈りだった。|{a}は夜ごと、{b}の無事を確かめてから眠った。そうしないと、目を閉じられなかった。|{a}は{b}の好きなものを、{b}よりも正確に覚えていた。'),
grow:{
'':L('{b}はようやく、{a}がずっと自分を見ていたことに気づいた。{b}「……いつから？｜……いつからだ｜……いつからですか」{a}「最初から｜最初からだ｜最初からです」{b}は答えに困って、それでも目を逸らさなかった。|{b}は{a}の献身の理由を、初めて真剣に訊いた。{a}は少し考えてから、「{b}が{b}だから｜{b}が{b}だからだ｜{b}が{b}だからです」とだけ答えた。'),
accept:L('{b}「{a}がいてくれて、{一人称}は救われてる｜{a}がいてくれて、{一人称}は救われている｜{a}がいてくれて、{一人称}は救われています」{a}は言葉を失って、ただ深く頭を下げた。信じてきた人に、初めて報われた気がした。|{b}は{a}に、自分の弱さを一つだけ見せた。{a}はそれを、宝物のように受け取った。崇める想いに、守りたいという想いが重なった。'),
confused:L('{b}は{a}に、もうやめてほしいと言った。{a}は静かに頷いて、それでも最後にこう言った。{a}「やめられない。{b}を想うことは、{一人称}の一部だから｜やめられない。{b}を想うことは、{一人称}の一部だ｜やめられません。{b}を想うことは、{一人称}の一部ですから」|{b}は{a}の重さから逃げるのをやめて、正面から向き合った。{b}「なら、せめて自分を粗末にしないで｜なら、せめて自分を粗末にするな｜なら、せめて自分を粗末にしないでください」{a}は少しだけ迷ってから、その約束を受け入れた。'),
cherish:L('{b}は{a}を抱き寄せた。{b}「崇められなくていい。{a}が隣にいてくれれば、それでいい｜＝｜崇められなくていいです。{a}が隣にいてくれれば、それでいいんです」{a}は震える手で、{b}の服の裾を掴んだ。|{b}は{a}に、かしこまらずに名前で呼んでほしいと言った。{a}は何度も口ごもってから、やっと{b}の名前を呼んだ。')
},
rule:L('{b}は{a}の顎に指をかけて、顔を上げさせた。{b}「{a}は、{一人称}のものだよね｜{a}は、{一人称}のものだな｜{a}は、{一人称}のものですよね」{a}「うん。{b}のもの｜ああ。{b}のものだ｜はい。{b}のものです」――答えた瞬間、{a}の中で何かが静かに定まった。|{b}は{a}に、明日の分まで指示を言い渡した。{a}は一つ残らず覚えて、{b}の望むとおりに動いた。{b}の支配が深まるほど、{a}の顔は穏やかになっていった。|{a}は{b}の足もとに膝をついた。{b}は止めなかった。二人のあいだの上下は、もう誰にも崩せないほど固まっていた。|{b}は{a}がほかの誰かに笑いかけたのを咎めた。{a}は青ざめて謝り、二度としないと誓った。{b}はその誓いを、当然のように受け取った。'),
love:L('{b}は{a}の手を取った。{b}「崇められるより、隣にいてほしい｜＝｜崇められるより、隣にいてほしいです」{a}は震える声で、{b}の名前を呼んだ。祈るような想いが、恋という形を見つけた。|{a}は{b}に触れられて、息を止めた。ずっと遠くから仰いでいた人が、今は手の届くところにいた。{a}「{b}を、好きになってもいいの？｜{b}を、好きになってもいいのか｜{b}を、好きになってもいいですか」{b}「とっくに、なってる｜とっくに、なっている｜とっくに、なっていますよ」|{a}は{b}への想いが、崇めるだけのものではなくなっていることに気づいた。{a}「ごめん。{b}を、ひとりの人として好きになった｜すまない。{b}を、ひとりの人として好きになった｜ごめんなさい。{b}を、ひとりの人として好きになりました」{b}は少し驚いて、それから笑って{a}を引き寄せた。')
};
push({
id:'tie_worship',label:'崇める相手に尽くす',cat:'help',scope:'pair',
when:function(ctx,a,b){return!!has(ctx,a,b,'worship');},
w:function(ctx){return 1.15*own(ctx);},
run:function(ctx,a,b){
var t=has(ctx,a,b,'worship'),S=ctx.chars[t.a],K=ctx.chars[t.b];
var cold=HK.WORSHIP_BACK&&HK.WORSHIP_BACK[t.cold]?t.cold:'';
var rs=ctx.R(S,K),rk=ctx.R(K,S),pf=ctx.pair(S,K),k,text;
var dom=cold==='dominate'||pf.dominate===K.i;
var loveOk=t.love==='ok'&& !(HK.tieOptNoLove&&HK.tieOptNoLove(t))&&both(S,K)&& !dom;
var cold2=rk.aff<0||rk.ten>40||(cold==='confused'&&rk.aff<15);
var x=ctx.rng();
if(loveOk&&rs.att>26&&rk.att>18&&rk.aff>25&&x<0.4)k='love';
else if(dom&&x<0.4)k='rule';
else if(cold2&&x<0.45)k='spurn';
else if((rk.aff>18||cold==='')&&x<0.6&&ctx.rng()<0.45)k='grow';
else k=ctx.rng()<0.3?'keep':'pat';
if(k==='pat'){
text=ctx.t(ctx.pick(WS.a),S,K);
if(ctx.rng()<0.75)text+=ctx.t(ctx.pick(WS.back[dom?'dominate':cold]),S,K);
ctx.mod2(S,K,{aff:2,trust:2},dom?{trust:3}:cold==='confused'?{ten:2,aff:1}:{aff:3,trust:2});
}else if(k==='keep'){
text=ctx.t(ctx.pick(WS.keep),S,K);
ctx.mod2(S,K,{aff:3,trust:3},dom?{trust:3}:{aff:3,trust:3});
}else if(k==='spurn'){
text=ctx.t(ctx.pick(WS.spurn),S,K);
ctx.mod2(S,K,{aff:2,trust:1},{ten:2,aff:1});
ctx.stress(S,4);
}else if(k==='rule'){
text=ctx.t(ctx.pick(WS.rule),S,K);
ctx.mod2(S,K,{trust:5,aff:4},{trust:3,aff:1});
grow(ctx,S,K,'worship_rule');
}else if(k==='love'){
text=ctx.t(ctx.pick(WS.love),S,K);
ctx.mod2(S,K,{att:8,aff:4},{att:8,aff:5});
grow(ctx,S,K,'worship');
}else{
var gk=dom?'accept':cold;
text=ctx.t(ctx.pick(WS.grow[gk]),S,K);
ctx.mod2(S,K,{aff:4,trust:4},cold==='confused'?{aff:5,ten: -4}:{aff:6,trust:6});
grow(ctx,S,K,'worship');
}
var why=S.name+'は'+K.name+'を信仰している'+(cold&&HK.WORSHIP_BACK[cold].short?'（'+K.name+'：'+HK.WORSHIP_BACK[cold].short+'）':'');
why+={pat:'：捧げる日々',keep:'：変わらない祈り',spurn:'：拒まれても揺るがない想い',rule:'：支配と服従が深まる',love:'：信仰が恋に変わる',grow:'：想いが届きはじめる'}[k];
return{cat:k==='love'?'romance':k==='spurn'?'conflict':k==='rule'?'bond':'help',text:text,why:why};
}
});
var LABELS={
wdevote:{name:'信仰を捧げたまま',cls:'guard',pol:1},
wsubmit:{name:'支配と服従',cls:'obsess',pol:0},
repaid:{name:'恩を返した',cls:'partner',pol:2},
bossbeyond:{name:'上司と部下を越えた',cls:'partner',pol:2},
classre:{name:'昔の同級生から特別な人へ',cls:'friend',pol:2},
relbond:{name:'親族として支え合う',cls:'partner',pol:2}
};
TR.LABELS=LABELS;
TR.install=function(){if(HK.LABELS)for(var k in LABELS)if(!HK.LABELS[k])HK.LABELS[k]=LABELS[k];};
var SOFT= /^(friends|partners|guard|strangers|awkward|oneway|obsess|dislike|pining|kinbond|accomplice)$/;
TR.refine=function(ctx,A,B,pf,cl){
if(!cl|| !HK.Ties|| !SOFT.test(cl.id)||pf.kill||pf.couple)return null;
TR.install();
var G=pf.tieGrow||{},t;
if((t=has(ctx,A,B,'worship'))){
var S=ctx.chars[t.a],K=ctx.chars[t.b],rs=ctx.R(S,K);
if((pf.dominate===K.i||t.cold==='dominate')&&rs.aff>=30&&cl.id!=='pining')return{id:'wsubmit',dir:S.i};
if(rs.aff>=30&&cl.id!=='pining'&&cl.id!=='partners')return{id:'wdevote',dir:S.i};
}
var ab=ctx.R(A,B),ba=ctx.R(B,A),warm=ab.aff>22&&ba.aff>22;
if((t=has(ctx,A,B,'benefactor'))&&G.benefactor&&warm&& /^(friends|partners|guard)$/.test(cl.id))return{id:'repaid',dir:t.b};
if((t=has(ctx,A,B,'boss'))&&G.boss&&warm&&ab.trust>30&&ba.trust>30&& /^(friends|partners|guard)$/.test(cl.id))return{id:'bossbeyond'};
if(has(ctx,A,B,'classmate')&&G.classmate&&ab.aff>35&&ba.aff>35&& /^(friends|partners)$/.test(cl.id))return{id:'classre'};
if(has(ctx,A,B,'relative')&&(G.relative||cl.id==='kinbond')&&warm&& /^(kinbond|guard|friends|partners)$/.test(cl.id))return{id:'relbond'};
return null;
};
TR.pairText=function(ctx,A,B,cl){
if(!cl|| !LABELS[cl.id])return null;
var n=function(i){return ctx.chars[i].name;},other=function(i){return i===A.i?B.name:A.name;};
switch(cl.id){
case'wdevote':return n(cl.dir)+'は最後まで'+other(cl.dir)+'を信じ、その想いを捧げ続けた。';
case'wsubmit':return other(cl.dir)+'が命じ、'+n(cl.dir)+'が従う。信仰は、支配と服従の形に固まった。';
case'repaid':return n(cl.dir)+'はようやく恩を返し、'+other(cl.dir)+'と並んで立てるようになった。';
case'bossbeyond':return'上司と部下という肩書きを越えて、互いを頼れる相手になった。';
case'classre':return'昔の同級生は、今はいちばん近くにいる特別な人になった。';
case'relbond':return cl.kin&&cl.kin!=='親戚'?cl.kin+'として、互いを支え合う形に落ち着いた。':'遠い親族だった二人が、家族として互いを支え合う形に落ち着いた。';
}
return null;
};
})();
});
;
