var fp0=V.fpDefault;
V.fpDefault=function(c){
var ex=c&&EX[c.tone];
if(ex&&ex.fp){var g=c.gender==='m'||c.gender==='f'?c.gender:'x';return ex.fp[g];}
return fp0(c);
};
function endRe(s){return new RegExp(s+'(?=[。！？!?…、」]|$)','g');}
