var MX_FEM={ane:1,ojou:1},MX_NASAI={ane:1,ojou:1,keigo_bossy:1,gentleman:1,sondai:1,god:1,polite:1,devoted:1,kohai:1,genki:1,keigo_sarc:1,keigo_flat:1,keigo_twist:1,chara_down:1,otaku:1,mixed:1};
