if(/来$/.test(st))return st+'い';
if(/[一-鿿々]し$/.test(st))return st+'ろ';
if(/[えけげせてねべめれ]$/.test(st)|| /(?:^|[^一-鿿々])[見寝着居出]$/.test(st))return st+'ろ';
if(MX_ICHI_I.test(st))return st+'ろ';
