var VERB='(?:[るつむぬぶぐたい]|(?<![まで])す|[一-鿿々]んだ|(?<!し)く|(?<![おこごそぞとどのほぼぽもよょろ])う)',VERBQ='(?:[るつむぬぶぐたい]|(?<![まで])す|(?<!し)く|(?<![おこごそぞとどのほぼぽもよょろ])う)';
