A.forEach(function(c){var m=X.mood(c);if(m!=='calm')(md=md||{})[c.i]=m;});
if(md)e.md=md;
if(ctx._emoWhy&&kind!=='phase'){e.why=(e.why?e.why+'／':'')+'気分：'+ctx._emoWhy.join('、');ctx._emoWhy=null;}
