function prefer(a,b){
var fa=pf(a,b),fb0=pf(b,a);
if(fa==='bottom'&&fb0!=='bottom')return[b,a];
if(fb0==='bottom'&&fa!=='bottom')return[a,b];
var la=P.lv(a),lb=P.lv(b);
if(la>lb)return[a,b];
if(lb>la)return[b,a];
return null;
}
