meters:o.meters||[],meta:o.meta||'',relmap:o.relmap||null,heroes:S.P.map(function(p){return{i:p.i,name:p.name,eg:p.eg,top:p.top,fate:p.fate,role:p.roleLabel||'',notes:p.notes,m:p.m,cnt:p.cnt};}),
stepCount:S.hist.length
