list.forEach(function(x){if(!who&&x&&x.name&&new RegExp(x.name.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?:の執着|の嫉妬・執着|による監禁|の囲い込み|の束縛|の[^。／（]{1,12}への執着)').test(w))who=x;});
who=who||list[0];
