var DB=K('hakoniwa-state'),OLD='hakoniwa-state',ST='state',KV='kv',VER=1;
var BIG=['state','state:backup','state:rescue'],WATCH={state:1,adv:1,history:1};
var LS_MAX=1000000,MARK='hakoniwa-idb',WAIT_MAX=8000;
