var from=st.tpage*TIE_PAGE,sl=ks.slice(from,from+TIE_PAGE),rows=HK.TiesUI?HK.TiesUI.rowsHtml(T,sl,lastTieRow,ks):sl.map(function(k){return lastTieRow(T[k],k);}).join('');
