var sp=seg.rows&&r.t&& !r.dirty?split(seg):null,dim= !(sp&&sp.head===r.t.sp.head);
r.stale=true;r.nodes.forEach(function(x){if(x.nodeType===1){x.classList.add('bxstale');if(dim)x.classList.add('bxdim');}});
