if(o.live&& !o.live()){stop(host);return;}
if(!BD.stat.pendStart)BD.stat.pendStart=performance.now();
var t0=performance.now(),seg=my.list.shift();
if(seg)apply(host,order,seg,o);
if(o.after)o.after();
