function rowSex(c){
var b=[],g={m:'男性',f:'女性',x:'その他'}[c.gender],l={m:'対象：男性',f:'対象：女性',both:'対象：男女両方',none:'対象：なし'}[c.likes];
b.push(g||'性別：おまかせ');if(l)b.push(l);
if(c.pos)b.push({top:'攻め',bottom:'受け',riba:'リバ'}[c.pos]||'');
return b.filter(Boolean).join('・');
}
