var o={a:J.indexOf(t.a),b:J.indexOf(t.b),type:t.type,cold:HK.coldOpts&&HK.coldOpts(t.type)?t.cold||'':'',love:t.love==='ok'||t.love==='no'?t.love:''};
(HK.tieExtra?HK.tieExtra(t.type):[]).forEach(function(x){if(t[x.f])o[x.f]=t[x.f];});
