if(gcur.length>gmx){gcur=gcur.slice(0,gmx);toast('上限の'+gmx+'人まで参加にしました');}
else toast('「'+t.dataset.g+'」'+(act==='joingrpadd'?'を参加に加えました':'だけを参加にしました'));
