if(tt&&HK.TIE_XF.indexOf(t.dataset.p)>=0){if(t.value&& !(tt.type==='fiance'&&t.value==='eager'))tt[t.dataset.p]=t.value;else delete tt[t.dataset.p];save();renderCast();return;}
