if(HK.CastTools)HK.CastTools.bind({S:function(){return S;},max:MAX,io:function(){return{jp:jpOpen,pick:pickPanel()};},sampleLeft:function(){return sampleLeft().length;},dup:function(id){dupRes(id);}});
