box.innerHTML=S().chars.filter(function(x){return x!==c;}).map(function(o){return'<label><input type="checkbox" data-gf="keigo" data-o="'+esc(o.id)+'"'+(c.keigo&&c.keigo[o.id]?' checked':'')+'> '+esc(o.name)+'</label>';}).join('');
