var b=['口調：'+(c.tone?toneLabel(c.tone):'おまかせ（'+toneLabel(autoKey(c))+'）')];
if(c.fp)b.push('一人称：'+c.fp);
if(c.you)b.push('二人称：'+c.you);
if(HK.Ending&&HK.Ending.on(c))b.push(HK.Ending.labelFor(c));
