/* ==== js/notice.js ==== */
HK.Load.def(315,'js/notice.js',function(){
(function(){
'use strict';
var last=null;
function box(){return document.getElementById('notice');}
function shape(m){
var bx=m.querySelector('.modal-box');
if(!bx||bx.querySelector('.nobody'))return;
var h=bx.querySelector('.notice-title'),c=bx.querySelector('[data-act="notice-close"]'),row=c&&c.closest('.row');
var body=document.createElement('div');body.className='nobody';
Array.prototype.slice.call(bx.childNodes).forEach(function(n){if(n!==h&&n!==row)body.appendChild(n);});
bx.appendChild(body);
if(row){row.className='nofoot';row.removeAttribute('style');bx.appendChild(row);}
}
function open(){
var m=box();if(!m)return;
last=document.activeElement;
shape(m);
m.hidden=false;
if(window.HK&&window.HK.Modal)window.HK.Modal.lock(m);
var c=m.querySelector('[data-act="notice-close"]');if(c)c.focus();
}
function close(){
var m=box();if(!m||m.hidden)return;
m.hidden=true;
if(window.HK&&window.HK.Modal)window.HK.Modal.unlock(m);
if(last&&last.focus)try{last.focus({preventScroll:true});}catch(e){last.focus();}
last=null;
}
document.addEventListener('click',function(ev){
var t=ev.target.closest&&ev.target.closest('[data-act="notice-open"],[data-act="notice-close"]');
if(t){ev.preventDefault();if(t.getAttribute('data-act')==='notice-open')open();else close();return;}
var m=box();
if(m&& !m.hidden&&ev.target===m)close();
});
document.addEventListener('keydown',function(ev){
var m=box();
if(ev.key==='Escape'&&m&& !m.hidden){ev.preventDefault();close();}
});
window.HK=window.HK||{};
window.HK.Notice={open:open,close:close};
})();
});
;
/* ==== js/ui-fold.js ==== */
HK.Load.def(316,'js/ui-fold.js',function(){
(function(){
'use strict';
var HK=window.HK;
var CLOSED={'関係の結末':1,'住人ごとの読み解き':1};
var KEY=HK&&HK.STORE?HK.STORE.key('hakoniwa_fold_v1'):'hakoniwa_fold_v1',state={};
try{state=JSON.parse(localStorage.getItem(KEY)||'{}')||{};}catch(e){state={};}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){}}
function norm(t){return String(t||'').replace(/[\d０-９\/／\s　]+/g,'').slice(0,30);}
function fold(host){
if(!host)return;
var kids=Array.prototype.slice.call(host.children);
if(!kids.some(function(k){return k.tagName==='H2'&&k.classList.contains('sec');}))return;
var tab=host.id,cur=null;
kids.forEach(function(el){
if(el.tagName==='H2'&&el.classList.contains('sec')){
var title=norm(el.textContent.replace(/？/g,'')),k=tab+':'+title;
var d=document.createElement('details');
d.className='fold';
if(el.id){d.id='fold-'+el.id;}
var open=state[k]!=null?state[k]: !(tab==='view-result'&&CLOSED[title]);
if(open)d.open=true;
var s=document.createElement('summary');
host.insertBefore(d,el);
s.appendChild(el);
d.appendChild(s);
d.addEventListener('toggle',function(){state[k]=d.open;save();});
cur=d;
return;
}
if(el.classList&&el.classList.contains('nofold')){cur=null;return;}
if(cur)cur.appendChild(el);
});
}
HK.Fold={apply:fold};
function watch(id){
var host=document.getElementById(id);
if(!host||typeof MutationObserver==='undefined')return;
var busy=false;
new MutationObserver(function(){
if(busy)return;
busy=true;
try{fold(host);}finally{busy=false;}
}).observe(host,{childList:true});
fold(host);
}
function init(){if(typeof document==='undefined'||typeof document.getElementById!=='function')return;['view-cast','view-box','view-result'].forEach(watch);}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
});
;
